const request = $input.first().json;
const body = request.body && typeof request.body === 'object' ? request.body : request;
const allowedEvents = new Set(['page_view', 'chat_open', 'question', 'click_git', 'click_orioris', 'click_preuves']);
const clean = (value, max = 80) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const event = clean(body.event, 32);
const sessionId = clean(body.sessionId, 64);
if (!allowedEvents.has(event) || !/^[A-Za-z0-9_-]{8,64}$/.test(sessionId)) {
  return [{ json: { status: 400, ok: false, error: 'Événement invalide.' } }];
}

const state = $getWorkflowStaticData('global');
state.cvAnalytics = state.cvAnalytics || { totals: {}, campaigns: {}, sessions: {}, updatedAt: null };
const analytics = state.cvAnalytics;
const now = Date.now();
const minuteAgo = now - 60 * 1000;
const hourAgo = now - 60 * 60 * 1000;
const recent = (analytics.sessions[sessionId] || []).filter((timestamp) => timestamp > hourAgo);
if (recent.filter((timestamp) => timestamp > minuteAgo).length >= 60 || recent.length >= 500) {
  analytics.sessions[sessionId] = recent;
  return [{ json: { status: 429, ok: false, error: 'Trop d’événements.' } }];
}
recent.push(now);
analytics.sessions[sessionId] = recent;
for (const [key, timestamps] of Object.entries(analytics.sessions)) {
  const active = timestamps.filter((timestamp) => timestamp > hourAgo);
  if (active.length) analytics.sessions[key] = active;
  else delete analytics.sessions[key];
}

const source = clean(body.source) || 'direct';
const company = clean(body.company) || 'non_renseignee';
const target = clean(body.target);
const campaignKey = `${source}::${company}`;
analytics.totals[event] = (analytics.totals[event] || 0) + 1;
analytics.campaigns[campaignKey] = analytics.campaigns[campaignKey] || { source, company, events: {}, lastSeenAt: null };
analytics.campaigns[campaignKey].events[event] = (analytics.campaigns[campaignKey].events[event] || 0) + 1;
analytics.campaigns[campaignKey].lastSeenAt = new Date(now).toISOString();
analytics.updatedAt = new Date(now).toISOString();

return [{ json: { status: 202, ok: true, event, source, company, target } }];
